/** Copy only the verified WeChat runtime into the game package. */
const fs = require('node:fs/promises');
const path = require('node:path');
const crypto = require('node:crypto');
const ROOT = path.resolve(__dirname,'..');
const VERSION = '4.3.51';
async function main() {
  const source=path.join(ROOT,'node_modules/libpag-miniprogram');
  const manifest=JSON.parse(await fs.readFile(path.join(source,'package.json'),'utf8'));
  if(manifest.version!==VERSION) throw new Error('Expected libpag-miniprogram@'+VERSION+'; run npm ci first.');
  const output=path.join(ROOT,'game/vendor/pag');
  await fs.mkdir(output,{recursive:true});
  const original=await fs.readFile(path.join(source,'lib/libpag.js'),'utf8');
  // Keep SDK's window assignment local in both CommonJS and the browser preview.
  const script='// Generated by tools/sync-pag.cjs: libpag-miniprogram@'+VERSION+'\n'+
    '(function (exports, window) {\n'+original.replace(/^\/\/# sourceMappingURL=.*$/gm,'')+
    '\n})(exports, typeof globalThis !== "undefined" ? globalThis : GameGlobal);\n';
  await fs.writeFile(path.join(output,'libpag.js'),script);
  const wasm=await fs.readFile(path.join(source,'lib/libpag.wasm.br'));
  await fs.writeFile(path.join(output,'libpag.wasm.br'),wasm);
  await fs.copyFile(path.join(source,'LICENSE.txt'),path.join(output,'LICENSE.txt'));
  await fs.writeFile(path.join(output,'NOTICE.txt'),'libpag-miniprogram '+VERSION+'\nTencent/libpag: https://github.com/Tencent/libpag\nLicensed under Apache-2.0; see LICENSE.txt.\nThe SDK includes TGFX components under BSD-3-Clause; their notices remain in libpag.js.\n');
  await fs.writeFile(path.join(output,'manifest.json'),JSON.stringify({package:'libpag-miniprogram',version:VERSION,files:{
    'libpag.js':{bytes:Buffer.byteLength(script),sha256:crypto.createHash('sha256').update(script).digest('hex')},
    'libpag.wasm.br':{bytes:wasm.length,sha256:crypto.createHash('sha256').update(wasm).digest('hex')}
  }},null,2)+'\n');
  console.log('Synced PAG '+VERSION+' ('+Buffer.byteLength(script)+' JS + '+wasm.length+' compressed WASM bytes).');
}
main().catch(error=>{console.error(error);process.exitCode=1;});
